window.AUTH=window.AUTH||{};window.AUTH["10-694"]={"d":"10-694","id":"2011/10-694","n":"Judulang v. Holder","src":["osg"],"briefs":[{"k":"respondent","label":"Brief for the respondent","date":"","url":"https://www.justice.gov/osg/media/196791/dl?inline","side":"res","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/judulang-v-holder-brief-merits","n":90}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep565/usrep565042/usrep565042.pdf","tr":true,"items":[{"t":"case","label":"Abebe v. Gonzales","cite":"493 F.3d 1092","y":2007,"url":"https://www.courtlistener.com/c/F.3d/493/1092/","op":1,"by":{"0":"14"}},{"t":"case","label":"Abebe v. Mukasey","cite":"554 F.3d 1203","y":2009,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/554/1203/","by":{"0":"14, 18, 51"}},{"t":"case","label":"Aguilar-Ramos v. Holder","cite":"594 F.3d 701","y":2010,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/594/701/","sum":"Holding there was no “authority to waive the second ground for Aguilar’s removal—conviction of two crimes involving moral turpitude—because Aguilar did not plead to the second crime involving moral turpitude until after Congress repealed section 212(c)”.","sumSrc":"brief:0","by":{"0":"17, 48"}},{"t":"case","label":"Ajdin v. Bureau of Citizenship & Immigration Servs.","cite":"437 F.3d 261","y":2006,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/437/261/","sum":"Finding the Board’s “apparent inconsistency” with one of its prior decisions to be “of no moment because unpublished opinions of the BIA have no precedential value”.","sumSrc":"brief:0","by":{"0":"35"}},{"t":"case","label":"Alvarez v. Mukasey","cite":"282 Fed. Appx. 718","y":2008,"court":"10th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./282/718/","by":{"0":"17"}},{"t":"case","label":"Blake v. Carbone","cite":"489 F.3d 88","y":2007,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/489/88/","op":12,"ar":14,"sum":"Rejecting the BIA’s approach and holding instead that “[i]f the offense that renders [an alien] deportable would render a similarly situated [alien] excludable, the deportable [alien] is eligible for a waiver of deportation”.","sumSrc":"opinion","by":{"0":"passim"}},{"t":"case","label":"Calderon-Minchola v. Attorney Gen.","cite":"258 Fed. Appx. 425","y":2007,"court":"3d Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./258/425/","sum":"Finding that crimes of violence in 18 U.S.C. 16(a) “would appear to require none of the vileness, depravity, or reprehensible acts deliberately committed that we have held are characteristic of moral turpitude”.","sumSrc":"brief:0","by":{"0":"28"}},{"t":"case","label":"Caroleo v. Gonzales","cite":"476 F.3d 158","y":2007,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/476/158/","op":1,"sum":"Concluding that the “statutory counterpart” principle “has been firmly in place and consistently applied since at least 1991”.","sumSrc":"brief:0","by":{"0":"17, 20, 39"}},{"t":"case","label":"Chevron U.S.A. Inc. v. NRDC","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"op":2,"sum":"The Supreme Court held that the bubble regulation was a reasonable interpretation of the term “stationary source” in the Clean Air Act. Congress did not have a specific intention for the interpretation of that term, and the EPA’s regulation was a reasonable policy choice. The regulation also provided reasonable accommodations for the many competing interests affected by the Act.","sumSrc":"Oyez","by":{"0":"28, 46"}},{"t":"case","label":"De Araujo v. Gonzales","cite":"457 F.3d 146","y":2006,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/457/146/","by":{"0":"34"}},{"t":"case","label":"De la Rosa v. Attorney Gen.","cite":"579 F.3d 1327","y":2009,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/579/1327/","op":1,"by":{"0":"17, 18, 20, 39"}},{"t":"case","label":"Duhaney v. Attorney Gen.","cite":"621 F.3d 340","y":2010,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/621/340/","by":{"0":"48"}},{"t":"case","label":"Fernandez-Vargas v. Gonzales","cite":"548 U.S. 30","y":2006,"id":"2005/04-1376","sc":1,"sum":"The Court ruled that the reinstatement statute does apply to illegal aliens who re-entered the U.S. before the effective date of the statute, and that the application to such aliens was not impermissibly retroactive.","sumSrc":"Oyez","by":{"0":"45"}},{"t":"case","label":"Fiallo v. Bell","cite":"430 U.S. 787","y":1977,"id":"1976/75-6297","sc":1,"sum":"Sections 101 (b) (1) (D) and 101 (b) (2) of the Immigration and Nationality Act of 1952, which have the effect of excluding the relationship between an illegitimate child and his natural father (as opposed to his natural mother) from the special preference immigration status accorded by the Act to the \"child\" or \"parent\" of a United States citizen or lawful permanent resident, held not to be unconstitutional.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"49, 52"}},{"t":"case","label":"Francis v. INS","cite":"532 F.2d 268","y":1976,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/532/268/","op":2,"ar":1,"by":{"0":"6, 18, 50"}},{"t":"case","label":"Frederick v. Holder","cite":"644 F.3d 357","y":2011,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/644/357/","by":{"0":"50"}},{"t":"case","label":"Galvan v. Press","cite":"347 U.S. 522","y":1954,"id":"scdb/1953-075","sc":1,"sum":"1. Section 22 of the Internal Security Act of 1950, providing for the deportation of any alien who has been a member of the Communist Party at any time after entry, is constitutional-as here applied to a resident alien shown to have been willingly a member of the Communist Party from 1944 to 1946 although not shown to have been aware of its advocacy of violent overthrow of the Government.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"49"}},{"t":"case","label":"Garcia-Lopez v. Ashcroft","cite":"334 F.3d 840","y":2003,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/334/840/","sum":"Recognizing grand theft under California law as a crime involving moral turpitude.","sumSrc":"brief:0","by":{"0":"48"}},{"t":"case","label":"Hem v. Maurer","cite":"458 F.3d 1185","y":2006,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/458/1185/","by":{"0":"34"}},{"t":"case","label":"INS v. Aguirre-Aguirre","cite":"526 U.S. 415","y":1999,"id":"1998/97-1754","sc":1,"sum":"The Court noted that withholding of deportation is mandatory if an alien establishes that it is more likely than not that he or she will suffer political persecution if deported.","sumSrc":"Oyez","by":{"0":"20, 30"}},{"t":"case","label":"INS v. Doherty","cite":"502 U.S. 314","y":1992,"id":"1991/90-925","sc":1,"sum":"The judgment is reversed. 908 F. 2d 1108, reversed. THE CHIEF JUSTICE delivered the opinion of the Court with respect to Part I, concluding that the Attorney General did not abuse his discreCite as: 502 U. S. 314 (1992) tion in denying the motion to reopen Doherty's deportation proceedings. There is no statutory provision for reopening, and the authority for such motions derives solely from regulations promulgated …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47"}},{"t":"case","label":"INS v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"op":2,"sum":"The Court held that habeas jurisdiction was not repealed by AEDPA and IIRIRA.","sumSrc":"Oyez","by":{"0":"3, 19, 44, 45"}},{"t":"case","label":"Jama v. Immigration & Customs Enforcement","cite":"543 U.S. 335","y":2005,"id":"2004/03-674","sc":1,"sum":"Federal immigration law permitted an alien to be removed to a country without the advance consent of that country's government. Of the four removal options federal immigration law listed, an acceptance requirement appeared in only one clause: \"...he shall be removed to another country whose government will accept him.\" That clause only applied after the attorney general attempted the prior deportation option.","sumSrc":"Oyez","by":{"0":"3"}},{"t":"case","label":"Jurado-Gutierrez v. Greene","cite":"190 F.3d 1135","y":1999,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/190/1135/","by":{"0":"51"}},{"t":"case","label":"Kim v. Gonzales","cite":"468 F.3d 58","y":2006,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/468/58/","op":1,"by":{"0":"17"}},{"t":"case","label":"Kleindienst v. Mandel","cite":"408 U.S. 753","y":1972,"id":"1971/71-16","sc":1,"sum":"The Court held that the First Amendment did not obligate Kleindienst to grant a waiver to Mandel.","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"Koussan v. Holder","cite":"556 F.3d 403","y":2009,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/556/403/","op":1,"sum":"Upholding the comparablegrounds policy.","sumSrc":"opinion","by":{"0":"17"}},{"t":"case","label":"LaGuerre v. Reno","cite":"164 F.3d 1035","y":1998,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/164/1035/","by":{"0":"51"}},{"t":"case","label":"Landon v. Plasencia","cite":"459 U.S. 21","y":1982,"id":"1982/81-129","sc":1,"op":1,"sum":"Section 235 of the Immigration and Nationality Act of 1952 (Act) permits the Immigration and Naturalization Service (INS) to examine \"all aliens\" who seek \"admission or readmission to\" the United States and empowers immigration officers to take evidence concerning the privilege of any persons suspected of being an alien \"to enter, reenter, pass through, or reside\" in the United States, and to detain for further …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2, 25"}},{"t":"case","label":"Leng May Ma v. Barber","cite":"357 U.S. 185","y":1958,"id":"1957/105","sc":1,"sum":"Her release on parole did not alter her status as an excluded alien; she was not \"within the United States,\" within the meaning of § 243 (h); and thus she was not eligible for the benefits of that section. Pp. 185-190. 241 F. 2d 85, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2"}},{"t":"case","label":"Lorillard v. Pons","cite":"434 U.S. 575","y":1978,"id":"1977/76-1346","sc":1,"by":{"0":"19"}},{"t":"case","label":"Miller v. Albright","cite":"523 U.S. 420","y":1998,"id":"1997/96-1060","sc":1,"sum":"After ruling that Miller had standing to challenge the constitutionality of a federal statute, the Court held that 8 U.S.C. Section 1409 did not violate the Equal Protection Clause.","sumSrc":"Oyez","by":{"0":"52, 53"}},{"t":"case","label":"Negusie v. Holder","cite":"129 S. Ct. 1159","y":2009,"id":"2008/07-499","sc":1,"sum":"The Court held that the Board of Immigration Appeals (BIA) incorrectly interpreted provisions of the Immigration and Nationality Act (INA) from a mistaken legal premise.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"Nguyen v. INS","cite":"533 U.S. 53","y":2001,"id":"2000/99-2071","sc":1,"op":1,"sum":"The Court held that Section 1409(a) comports with the constitutional guarantee of equal protection. \"For a gender-based classification to withstand equal protection scrutiny, it must be established 'at least that the [challenged] classification serves important governmental objectives and that the discriminatory means employed are substantially related to the achievement of those objectives,'\" wrote Justice Kennedy.","sumSrc":"Oyez","by":{"0":"53"}},{"t":"case","label":"NLRB v. Majestic Weaving Co.","cite":"355 F.2d 854","y":1966,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/355/854/","by":{"0":"44"}},{"t":"case","label":"Oceanic Steam Navigation Co. v. Stranahan","cite":"214 U.S. 320","y":1909,"id":"scdb/1908-176","sc":1,"sum":"Money paid to the collector of a port under protest, and on the certainty that if not paid clearance to vessels necessarily sailing on definite schedule would be refused, to the great damage of the owner, is paid involuntarily,'and can, if unlawfully exacted, be recovered;","sumSrc":"Headnote (U.S. Reports)","by":{"0":"49"}},{"t":"case","label":"Paulo v. Holder","cite":"2011 WL 1663572","y":2011,"court":"9th Cir. May 4","by":{"0":"38"}},{"t":"case","label":"Quintero-Salazar v. Keisler","cite":"506 F.3d 688","y":2007,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/506/688/","sum":"Finding that, although California statutory-rape offense was “crime of violence” under Sentencing Guidelines, it was not “crime of moral turpitude” for immigration purposes.","sumSrc":"brief:0","by":{"0":"28"}},{"t":"case","label":"Requena-Rodriguez v. Pasquarell","cite":"190 F.3d 299","y":1999,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/190/299/","by":{"0":"51"}},{"t":"case","label":"Retail, Wholesale & Dep’t Store Union v. NLRB","cite":"466 F.2d 380","y":1972,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/466/380/","by":{"0":"43"}},{"t":"case","label":"SEC v. Chenery Corp.","cite":"332 U.S. 194","y":1947,"id":"scdb/1946-133","sc":1,"ar":1,"sum":"The new order is sustained. Pp. 196-199, 209.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43"}},{"t":"case","label":"Shaughnessy v. Mezei","cite":"345 U.S. 206","y":1953,"id":"scdb/1952-067","sc":1,"sum":"The Attorney General's continued exclusion of the alien without a hearing does not amount to an unlpvful detention, and courts may not temporarily admit him to the iJnited States pending arrangements for his departure abroad.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"49"}},{"t":"case","label":"Stone v. INS","cite":"514 U.S. 386","y":1995,"id":"1994/93-1199","sc":1,"sum":"A timely motion for reconsideration of a BIA decision does not toll the running of § 106(a)(1)'s 90-day period.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47"}},{"t":"case","label":"Thap v. Mukasey","cite":"544 F.3d 674","y":2008,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/544/674/","by":{"0":"51"}},{"t":"case","label":"United States v. Ubaldo-Figueroa","cite":"364 F.3d 1042","y":2004,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/364/1042/","by":{"0":"34, 35"}},{"t":"case","label":"Valere v. Gonzales","cite":"473 F.3d 757","y":2007,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/473/757/","sum":"Finding “application of Blake * * * is not impermissibly retroactive” because “the rule itself is not new,” although “the Blake decision marked the first time the BIA applied the rule to the crime of sexual assault of a minor”.","sumSrc":"brief:0","by":{"0":"39"}},{"t":"case","label":"Vo v. Gonzales","cite":"482 F.3d 363","y":2007,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/482/363/","sum":"Finding the Board’s interpretation of the statutory-counterpart rule was not “irrational or arbitrary and capricious” because there had been no “substantial shift in agency practice”.","sumSrc":"brief:0","by":{"0":"17, 39, 51"}},{"t":"case","label":"Vue v. Gonzales","cite":"496 F.3d 858","y":2007,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/496/858/","by":{"0":"17, 20"}},{"t":"case","label":"Zamora-Mallari v. Mukasey","cite":"514 F.3d 679","y":2008,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/514/679/","by":{"0":"17, 39"}},{"t":"const","label":"Amendment V","clauses":[["due-process-5","Due Process Clause (Fifth Amendment)"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"0":"17"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","subs":["(2)(A)"],"stext":{"head":"§706. Scope of review","paras":[[0,"To the extent necessary to decision and when presented, the reviewing court shall decide all relevant questions of law, interpret constitutional and statutory provisions, and determine the meaning or applicability of the terms of an agency action. The reviewing court shall—"],[1,"(1) compel agency action unlawfully withheld or unreasonably delayed; and"],[1,"(2) hold unlawful and set aside agency action, findings, and conclusions found to be—"],[2,"(A) arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law;"],[2,"(B) contrary to constitutional right, power, privilege, or immunity;"],[2,"(C) in excess of statutory jurisdiction, authority, or limitations, or short of statutory right;"],[2,"(D) without observance of procedure required by law;"],[2,"(E) unsupported by substantial evidence in a case subject to sections 556 and 557 of this title or otherwise reviewed on the record of an agency hearing provided by statute; or"],[2,"(F) unwarranted by the facts to the extent that the facts are subject to trial de novo by the reviewing court."],[0,"In making the foregoing determinations, the court shall review the whole record or those parts of it cited by a party, and due account shall be taken of the rule of prejudicial error."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/5/706?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§706. Scope of review","tname":"Government Organization and Employees","by":{"0":"19"}},{"t":"law","label":"Pub. L. No. 104-132","url":"https://www.govinfo.gov/link/plaw/104/public/132","by":{"0":"8, 19, 53"}},{"t":"law","label":"Pub. L. No. 104-208","url":"https://www.govinfo.gov/link/plaw/104/public/208","by":{"0":"2, 3, 8, 12, 48"}},{"t":"law","label":"Pub. L. No. 101-649","url":"https://www.govinfo.gov/link/statute/104/4978","by":{"0":"8"}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","subs":["(a)(43)","(a)(43)(1988)","(a)(43)(A)","(a)(43)(B)(1994)","(a)(43)(F)","(a)(43)(G)","(a)(43)(U)","(a)(48)(B)"],"stext":{"head":"§1101. Definitions","paras":[[0,"(a) As used in this chapter—"],[0,"(1) The term \"administrator\" means the official designated by the Secretary of State pursuant to section 1104(b) of this title."],[0,"(2) The term \"advocates\" includes, but is not limited to, advises, recommends, furthers by overt act, and admits belief in."],[0,"(3) The term \"alien\" means any person not a citizen or national of the United States."],[0,"(4) The term \"application for admission\" has reference to the application for admission into the United States and not to the application for the issuance of an immigrant or nonimmigrant visa."],[0,"(5) The term \"Attorney General\" means the Attorney General of the United States."],[0,"(6) The term \"border crossing identification card\" means a document of identity bearing that designation issued to an alien who is lawfully admitted for permanent residence, or to an alien who is a resident in foreign contiguous territory, by a consular officer or an immigration officer for the purpose of crossing over the borders between the United States and foreign contiguous territory in accordance with such conditions for its issuance and use as may be prescribed by regulations. Such regulations shall provide that (A) each such document include a biometric identifier (such as the fingerprint or handprint of the alien) that is machine readable and (B) an alien presenting a border crossing identification card is not permitted to cross over the border into the United States unless the biometric identifier contained on the card matches the appropriate biometric characteristic of the alien."],[0,"(7) The term \"clerk of court\" means a clerk of a naturalization court."],[0,"(8) The terms \"Commissioner\" and \"Deputy Commissioner\" mean the Commissioner of Immigration and Naturalization and a Deputy Commissioner of Immigration and Naturalization, respectively."],[0,"(9) The term \"consular officer\" means any consular, diplomatic, or other officer or employee of the United States designated under regulations prescribed under authority contained in this chapter, for the purpose of issuing immigrant or nonimmigrant visas or, when used in subchapter III, for the purpose of adjudicating nationality."],[0,"(10) The term \"crewman\" means a person serving in any capacity on board a vessel or aircraft."],[0,"(11) The term \"diplomatic visa\" means a nonimmigrant visa bearing that title and issued to a nonimmigrant in accordance with such regulations as the Secretary of State may prescribe."],[0,"(12) The term \"doctrine\" includes, but is not limited to, policies, practices, purposes, aims, or procedures."],[0,"(13)(A) The terms \"admission\" and \"admitted\" mean, with respect to an alien, the lawful entry of the alien into the United States after inspection and authorization by an immigration officer."],[0,"(B) An alien who is paroled under section 1182(d)(5) of this title or permitted to land temporarily as an alien crewman shall not be considered to have been admitted."],[0,"(C) An alien lawfully admitted for permanent residence in the United States shall not be regarded as seeking an admission into the United States for purposes of the immigration laws unless the alien—"],[1,"(i) has abandoned or relinquished that status,"],[1,"(ii) has been absent from the United States for a continuous period in excess of 180 days,"],[1,"(iii) has engaged in illegal activity after having departed the United States,"],[1,"(iv) has departed from the United States while under legal process seeking removal of the alien from the United States, including removal proceedings under this chapter and extradition proceedings,"],[1,"(v) has committed an offense identified in section 1182(a)(2) of this title, unless since such offense the alien has been granted relief under section 1182(h) or 1229b(a) of this title, or"],[1,"(vi) is attempting to enter at a time or place other than as designated by immigration officers or has not been admitted to the United States after inspection and authorization by an immigration officer."],[0,"(14) The term \"foreign state\" includes outlying possessions of a foreign state, but self-governing dominions or territories under mandate or trusteeship shall be regarded as separate foreign states."],[0,"(15) The term \"immigrant\" means every alien except an alien who is within one of the following classes of nonimmigrant aliens—"],[1,"(A)(i) an ambassador, public minister, or career diplomatic or consular officer who has been accredited by a foreign government, recognized de jure by the United States and who is accepted by the President or by the Secretary of State, and the members of the alien's immediate family;"],[1,"(ii) upon a basis of reciprocity, other officials and employees who have been accredited by a foreign government recognized de jure by the United States, who are accepted by the Secretary of State, and the members of their immediate families; and"],[1,"(iii) upon a basis of reciprocity, attendants, servants, personal employees, and members of their immediate families, of the officials and employees who have a nonimmigrant status under (i) and (ii) above;"],[1,"(B) an alien (other than one coming for the purpose of study or of performing skilled or unskilled labor or as a representative of foreign press, radio, film, or other foreign information media coming to engage in such vocation) having a residence in a foreign country which he has no intention of abandoning and who is visiting the United States temporarily for business or temporarily for pleasure;"],[1,"(C)(i) an alien in immediate and continuous transit through the United States, for a period not to exceed 29 days;"],[1,"(ii) an alien who qualifies as a person entitled to pass in transit to and from the United Nations Headquarters District (as defined in section 4309a(e) of title 22) and foreign countries, under the provisions of paragraphs (3), (4), and (5) of section 11 of the Agreement regarding the Headquarters of the United Nations, done at Lake Success June 26, 1947 (61 Stat. 758); or"],[1,"(iii) an alien passing in transit through the United States to board a vessel on which the alien will perform, or to disembark from a vessel on which the alien performed, ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, for a period not to exceed 180 days;"],[1,"(D)(i) an alien crewman serving in good faith as such in a capacity required for normal operation and service on board a vessel, as defined in section 1288(a) of this title (other than a fishing vessel having its home port or an operating base in the United States), or aircraft, who intends to land temporarily and solely in pursuit of his calling as a crewman and to depart from the United States with the vessel or aircraft on which he arrived or some other vessel or aircraft;"],[1,"(ii) an alien crewman serving in good faith as such in any capacity required for normal operations and service aboard a fishing vessel having its home port or an operating base in the United States who intends to land temporarily in Guam or the Commonwealth of the Northern Mariana Islands and solely in pursuit of his calling as a crewman and to depart from Guam or the Commonwealth of the Northern Mariana Islands with the vessel on which he arrived; or"],[1,"(iii) an alien crewman performing ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, who intends to land temporarily solely in pursuit of the alien's responsibilities as a crewman and to depart from the United States on the vessel on which the alien arrived or on another vessel or aircraft, for a period not to exceed 180 days;"],[1,"(E) an alien entitled to enter the United States under and in pursuance of the provisions of a treaty of commerce and navigation between the United States and the foreign state of which the alien is a national (or, in the case of an alien who acquired the relevant nationality through a financial investment and who has not previously been granted status under this subparagraph, the foreign state of which the alien is a national and in which the alien has been domiciled for a continuous period of not less than 3 years at any point before applying for a nonimmigrant visa under this subparagraph), and the spouse and children of any such alien if accompanying or following to join such alien; (i) solely to carry on substantial trade, including trade in services or trade in technology, principally between the United States and the foreign state of which the alien is a national; (ii) solely to develop and direct the operations of an enterprise in which the alien has invested, or of an enterprise in which the alien is actively in the process of investing, a substantial amount of capital; or (iii) solely to perform services in a specialty occupation in the United States if the alien is a national of the Commonwealth of Australia and with respect to whom the Secretary of Labor determines and certifies to the Secretary of Homeland Security and the Secretary of State that the intending employer has filed with the Secretary of Labor an attestation under section 1182(t)(1) of this title;"],[1,"(F)(i) an alien having a residence in a foreign country which he has no intention of abandoning, who is a bona fide student qualified to pursue a full course of study and who seeks to enter the United States temporarily and solely for the purpose of pursuing such a course of study consistent with section 1184(l) 1 of this title at an established college, university, seminary, conservatory, academic high school, elementary school, or other academic institution or in an accredited language training program in the United States, particularly designated by him and approved by the Attorney General after consultation with the Secretary of Education, which institution or place of study shall have agreed to report to the Attorney General the termination of attendance of each nonimmigrant student, and if any such institution of learning or place of study fails to make reports promptly the approval shall be withdrawn, (ii) the alien spouse and minor children of any alien described in clause (i) if accompanying or following to join such an alien, and (iii) an alien who is a national of Canada or Mexico, who maintains actual residence and place of abode in the country of nationality, who is described in clause (i) except that the alien's qualifications for and actual course of study may be full or part-time, and who commutes to the United States institution or place of study from Canada or Mexico;"]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/8/1101?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1101. Definitions","tname":"Aliens and Nationality","by":{"0":"2, 8, 24, 8, 8, 33, 10, 31, 34, 36, 44, 8, 13, 24, 36, 37, passim, 36, 8"}},{"t":"usc","label":"8 U.S.C. § 1158","url":"https://www.law.cornell.edu/uscode/text/8/1158","subs":["(b)(2)(B)(I)"],"by":{"0":"24"}},{"t":"usc","label":"8 U.S.C. § 1182","url":"https://www.law.cornell.edu/uscode/text/8/1182","subs":["(a)(1994)","(a)","(a)(2)(A)(i)(I)","(a)(9)(1988)","(a)(9)(A)(ii)","(c)(1952)","(c)(1994)"],"stext":{"head":"§1182. Inadmissible aliens","paras":[[0,"(a) Classes of aliens ineligible for visas or admission"],[0,"Except as otherwise provided in this chapter, aliens who are inadmissible under the following paragraphs are ineligible to receive visas and ineligible to be admitted to the United States:"],[0,"(1) Health-related grounds"],[0,"(A) In general"],[2,"Any alien—"],[3,"(i) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services) to have a communicable disease of public health significance; 1"],[3,"(ii) except as provided in subparagraph (C), who seeks admission as an immigrant, or who seeks adjustment of status to the status of an alien lawfully admitted for permanent residence, and who has failed to present documentation of having received vaccination against vaccine-preventable diseases, which shall include at least the following diseases: mumps, measles, rubella, polio, tetanus and diphtheria toxoids, pertussis, influenza type B and hepatitis B, and any other vaccinations against vaccine-preventable diseases recommended by the Advisory Committee for Immunization Practices,"],[3,"(iii) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services in consultation with the Attorney General)—"],[4,"(I) to have a physical or mental disorder and behavior associated with the disorder that may pose, or has posed, a threat to the property, safety, or welfare of the alien or others, or"],[4,"(II) to have had a physical or mental disorder and a history of behavior associated with the disorder, which behavior has posed a threat to the property, safety, or welfare of the alien or others and which behavior is likely to recur or to lead to other harmful behavior, or"],[3,"(iv) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services) to be a drug abuser or addict,"],[2,"is inadmissible."],[0,"(B) Waiver authorized"],[2,"For provision authorizing waiver of certain clauses of subparagraph (A), see subsection (g)."],[0,"(C) Exception from immunization requirement for adopted children 10 years of age or younger"],[2,"Clause (ii) of subparagraph (A) shall not apply to a child who—"],[3,"(i) is 10 years of age or younger,"],[3,"(ii) is described in subparagraph (F) or (G) of section 1101(b)(1) of this title; 1 and"],[3,"(iii) is seeking an immigrant visa as an immediate relative under section 1151(b) of this title,"],[2,"if, prior to the admission of the child, an adoptive parent or prospective adoptive parent of the child, who has sponsored the child for admission as an immediate relative, has executed an affidavit stating that the parent is aware of the provisions of subparagraph (A)(ii) and will ensure that, within 30 days of the child's admission, or at the earliest time that is medically appropriate, the child will receive the vaccinations identified in such subparagraph."],[0,"(2) Criminal and related grounds"],[0,"(A) Conviction of certain crimes"],[0,"(i) In general"],[3,"Except as provided in clause (ii), any alien convicted of, or who admits having committed, or who admits committing acts which constitute the essential elements of—"],[4,"(I) a crime involving moral turpitude (other than a purely political offense) or an attempt or conspiracy to commit such a crime, or"],[4,"(II) a violation of (or a conspiracy or attempt to violate) any law or regulation of a State, the United States, or a foreign country relating to a controlled substance (as defined in section 802 of title 21),"],[0,"is inadmissible."],[0,"(ii) Exception"],[3,"Clause (i)(I) shall not apply to an alien who committed only one crime if—"],[4,"(I) the crime was committed when the alien was under 18 years of age, and the crime was committed (and the alien released from any confinement to a prison or correctional institution imposed for the crime) more than 5 years before the date of application for a visa or other documentation and the date of application for admission to the United States, or"],[4,"(II) the maximum penalty possible for the crime of which the alien was convicted (or which the alien admits having committed or of which the acts that the alien admits having committed constituted the essential elements) did not exceed imprisonment for one year and, if the alien was convicted of such crime, the alien was not sentenced to a term of imprisonment in excess of 6 months (regardless of the extent to which the sentence was ultimately executed)."],[0,"(B) Multiple criminal convictions"],[2,"Any alien convicted of 2 or more offenses (other than purely political offenses), regardless of whether the conviction was in a single trial or whether the offenses arose from a single scheme of misconduct and regardless of whether the offenses involved moral turpitude, for which the aggregate sentences to confinement were 5 years or more is inadmissible."],[0,"(C) Controlled substance traffickers"],[2,"Any alien who the consular officer or the Attorney General knows or has reason to believe—"],[3,"(i) is or has been an illicit trafficker in any controlled substance or in any listed chemical (as defined in section 802 of title 21), or is or has been a knowing aider, abettor, assister, conspirator, or colluder with others in the illicit trafficking in any such controlled or listed substance or chemical, or endeavored to do so; or"],[3,"(ii) is the spouse, son, or daughter of an alien inadmissible under clause (i), has, within the previous 5 years, obtained any financial or other benefit from the illicit activity of that alien, and knew or reasonably should have known that the financial or other benefit was the product of such illicit activity,"],[2,"is inadmissible."],[0,"(D) Prostitution and commercialized vice"],[2,"Any alien who—"],[3,"(i) is coming to the United States solely, principally, or incidentally to engage in prostitution, or has engaged in prostitution within 10 years of the date of application for a visa, admission, or adjustment of status,"],[3,"(ii) directly or indirectly procures or attempts to procure, or (within 10 years of the date of application for a visa, admission, or adjustment of status) procured or attempted to procure or to import, prostitutes or persons for the purpose of prostitution, or receives or (within such 10-year period) received, in whole or in part, the proceeds of prostitution, or"],[3,"(iii) is coming to the United States to engage in any other unlawful commercialized vice, whether or not related to prostitution,"],[2,"is inadmissible."],[0,"(E) Certain aliens involved in serious criminal activity who have asserted immunity from prosecution"],[2,"Any alien—"],[3,"(i) who has committed in the United States at any time a serious criminal offense (as defined in section 1101(h) of this title),"],[3,"(ii) for whom immunity from criminal jurisdiction was exercised with respect to that offense,"],[3,"(iii) who as a consequence of the offense and exercise of immunity has departed from the United States, and"],[3,"(iv) who has not subsequently submitted fully to the jurisdiction of the court in the United States having jurisdiction with respect to that offense,"],[2,"is inadmissible."],[0,"(F) Waiver authorized"],[2,"For provision authorizing waiver of certain subparagraphs of this paragraph, see subsection (h)."],[0,"(G) Foreign government officials who have committed particularly severe violations of religious freedom"],[2,"Any alien who, while serving as a foreign government official, was responsible for or directly carried out, at any time, particularly severe violations of religious freedom, as defined in section 6402 of title 22, is inadmissible."],[0,"(H) Significant traffickers in persons"],[0,"(i) In general"],[3,"Any alien who commits or conspires to commit human trafficking offenses in the United States or outside the United States, or who the consular officer, the Secretary of Homeland Security, the Secretary of State, or the Attorney General knows or has reason to believe is or has been a knowing aider, abettor, assister, conspirator, or colluder with such a trafficker in severe forms of trafficking in persons, as defined in the section 7102 of title 22, is inadmissible."],[0,"(ii) Beneficiaries of trafficking"],[3,"Except as provided in clause (iii), any alien who the consular officer or the Attorney General knows or has reason to believe is the spouse, son, or daughter of an alien inadmissible under clause (i), has, within the previous 5 years, obtained any financial or other benefit from the illicit activity of that alien, and knew or reasonably should have known that the financial or other benefit was the product of such illicit activity, is inadmissible."],[0,"(iii) Exception for certain sons and daughters"],[3,"Clause (ii) shall not apply to a son or daughter who was a child at the time he or she received the benefit described in such clause."],[0,"(I) Money laundering"],[2,"Any alien—"],[3,"(i) who a consular officer or the Attorney General knows, or has reason to believe, has engaged, is engaging, or seeks to enter the United States to engage, in an offense which is described in section 1956 or 1957 of title 18 (relating to laundering of monetary instruments); or"],[3,"(ii) who a consular officer or the Attorney General knows is, or has been, a knowing aider, abettor, assister, conspirator, or colluder with others in an offense which is described in such section;"],[2,"is inadmissible."]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/8/1182?type=usc&year=mostrecent&link-type=html"},"op":6,"head":"§1182. Inadmissible aliens","tname":"Aliens and Nationality","by":{"0":"17, 3, 10, 32, 37, 32, 24, 5, passim"}},{"t":"usc","label":"8 U.S.C. § 1227","url":"https://www.law.cornell.edu/uscode/text/8/1227","subs":["(a)","(a)(2)(A)(ii)","(a)(2)(A)(iii)"],"by":{"0":"3, 24, 12, 48, 12"}},{"t":"usc","label":"8 U.S.C. § 1229","url":"https://www.law.cornell.edu/uscode/text/8/1229","stext":{"head":"§1229. Initiation of removal proceedings","paras":[[0,"(a) Notice to appear"],[0,"(1) In general"],[1,"In removal proceedings under section 1229a of this title, written notice (in this section referred to as a \"notice to appear\") shall be given in person to the alien (or, if personal service is not practicable, through service by mail to the alien or to the alien's counsel of record, if any) specifying the following:"],[2,"(A) The nature of the proceedings against the alien."],[2,"(B) The legal authority under which the proceedings are conducted."],[2,"(C) The acts or conduct alleged to be in violation of law."],[2,"(D) The charges against the alien and the statutory provisions alleged to have been violated."],[2,"(E) The alien may be represented by counsel and the alien will be provided (i) a period of time to secure counsel under subsection (b)(1) and (ii) a current list of counsel prepared under subsection (b)(2)."],[2,"(F)(i) The requirement that the alien must immediately provide (or have provided) the Attorney General with a written record of an address and telephone number (if any) at which the alien may be contacted respecting proceedings under section 1229a of this title."],[2,"(ii) The requirement that the alien must provide the Attorney General immediately with a written record of any change of the alien's address or telephone number."],[2,"(iii) The consequences under section 1229a(b)(5) of this title of failure to provide address and telephone information pursuant to this subparagraph."],[2,"(G)(i) The time and place at which the proceedings will be held."],[2,"(ii) The consequences under section 1229a(b)(5) of this title of the failure, except under exceptional circumstances, to appear at such proceedings."],[0,"(2) Notice of change in time or place of proceedings"],[0,"(A) In general"],[2,"In removal proceedings under section 1229a of this title, in the case of any change or postponement in the time and place of such proceedings, subject to subparagraph (B) a written notice shall be given in person to the alien (or, if personal service is not practicable, through service by mail to the alien or to the alien's counsel of record, if any) specifying—"],[3,"(i) the new time or place of the proceedings, and"],[3,"(ii) the consequences under section 1229a(b)(5) of this title of failing, except under exceptional circumstances, to attend such proceedings."],[0,"(B) Exception"],[2,"In the case of an alien not in detention, a written notice shall not be required under this paragraph if the alien has failed to provide the address required under paragraph (1)(F)."],[0,"(3) Central address files"],[1,"The Attorney General shall create a system to record and preserve on a timely basis notices of addresses and telephone numbers (and changes) provided under paragraph (1)(F)."],[0,"(b) Securing of counsel"],[0,"(1) In general"],[1,"In order that an alien be permitted the opportunity to secure counsel before the first hearing date in proceedings under section 1229a of this title, the hearing date shall not be scheduled earlier than 10 days after the service of the notice to appear, unless the alien requests in writing an earlier hearing date."],[0,"(2) Current lists of counsel"],[1,"The Attorney General shall provide for lists (updated not less often than quarterly) of persons who have indicated their availability to represent pro bono aliens in proceedings under section 1229a of this title. Such lists shall be provided under subsection (a)(1)(E) and otherwise made generally available."],[0,"(3) Rule of construction"],[1,"Nothing in this subsection may be construed to prevent the Attorney General from proceeding against an alien pursuant to section 1229a of this title if the time period described in paragraph (1) has elapsed and the alien has failed to secure counsel."],[0,"(c) Service by mail"],[0,"Service by mail under this section shall be sufficient if there is proof of attempted delivery to the last address provided by the alien in accordance with subsection (a)(1)(F)."],[0,"(d) Prompt initiation of removal"],[0,"(1) In the case of an alien who is convicted of an offense which makes the alien deportable, the Attorney General shall begin any removal proceeding as expeditiously as possible after the date of the conviction."],[0,"(2) Nothing in this subsection shall be construed to create any substantive or procedural right or benefit that is legally enforceable by any party against the United States or its agencies or officers or any other person."],[0,"(e) Certification of compliance with restrictions on disclosure"],[0,"(1) In general"],[1,"In cases where an enforcement action leading to a removal proceeding was taken against an alien at any of the locations specified in paragraph (2), the Notice to Appear shall include a statement that the provisions of section 1367 of this title have been complied with."],[0,"(2) Locations"],[1,"The locations specified in this paragraph are as follows:"],[2,"(A) At a domestic violence shelter, a rape crisis center, supervised visitation center, family justice center, a victim services, or victim services provider, or a community-based organization."],[2,"(B) At a courthouse (or in connection with that appearance of the alien at a courthouse) if the alien is appearing in connection with a protection order case, child custody case, or other civil or criminal case relating to domestic violence, sexual assault, trafficking, or stalking in which the alien has been battered or subject to extreme cruelty or if the alien is described in subparagraph (T) or (U) of section 1101(a)(15) of this title."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/8/1229?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1229. Initiation of removal proceedings","tname":"Aliens and Nationality","by":{"0":"3"}},{"t":"usc","label":"8 U.S.C. § 1229a","url":"https://www.law.cornell.edu/uscode/text/8/1229a","subs":["(e)(2)"],"by":{"0":"3, 3"}},{"t":"usc","label":"8 U.S.C. § 1229b","url":"https://www.law.cornell.edu/uscode/text/8/1229b","subs":["(a)(3)","(b)(1)(C)"],"stext":{"head":"§1229b. Cancellation of removal; adjustment of status","paras":[[0,"(a) Cancellation of removal for certain permanent residents"],[0,"The Attorney General may cancel removal in the case of an alien who is inadmissible or deportable from the United States if the alien—"],[1,"(1) has been an alien lawfully admitted for permanent residence for not less than 5 years,"],[1,"(2) has resided in the United States continuously for 7 years after having been admitted in any status, and"],[1,"(3) has not been convicted of any aggravated felony."],[0,"(b) Cancellation of removal and adjustment of status for certain nonpermanent residents"],[0,"(1) In general"],[1,"The Attorney General may cancel removal of, and adjust to the status of an alien lawfully admitted for permanent residence, an alien who is inadmissible or deportable from the United States if the alien—"],[2,"(A) has been physically present in the United States for a continuous period of not less than 10 years immediately preceding the date of such application;"],[2,"(B) has been a person of good moral character during such period;"],[2,"(C) has not been convicted of an offense under section 1182(a)(2), 1227(a)(2), or 1227(a)(3) of this title, subject to paragraph (5); and"],[2,"(D) establishes that removal would result in exceptional and extremely unusual hardship to the alien's spouse, parent, or child, who is a citizen of the United States or an alien lawfully admitted for permanent residence."],[0,"(2) Special rule for battered spouse or child"],[0,"(A) Authority"],[2,"The Attorney General may cancel removal of, and adjust to the status of an alien lawfully admitted for permanent residence, an alien who is inadmissible or deportable from the United States if the alien demonstrates that—"],[3,"(i)(I) the alien has been battered or subjected to extreme cruelty by a spouse or parent who is or was a United States citizen (or is the parent of a child of a United States citizen and the child has been battered or subjected to extreme cruelty by such citizen parent);"],[3,"(II) the alien has been battered or subjected to extreme cruelty by a spouse or parent who is or was a lawful permanent resident (or is the parent of a child of an alien who is or was a lawful permanent resident and the child has been battered or subjected to extreme cruelty by such permanent resident parent); or"],[3,"(III) the alien has been battered or subjected to extreme cruelty by a United States citizen or lawful permanent resident whom the alien intended to marry, but whose marriage is not legitimate because of that United States citizen's or lawful permanent resident's bigamy;"],[3,"(ii) the alien has been physically present in the United States for a continuous period of not less than 3 years immediately preceding the date of such application, and the issuance of a charging document for removal proceedings shall not toll the 3-year period of continuous physical presence in the United States;"],[3,"(iii) the alien has been a person of good moral character during such period, subject to the provisions of subparagraph (C);"],[3,"(iv) the alien is not inadmissible under paragraph (2) or (3) of section 1182(a) of this title, is not deportable under paragraphs (1)(G) or (2) through (4) of section 1227(a) of this title, subject to paragraph (5), and has not been convicted of an aggravated felony; and"],[3,"(v) the removal would result in extreme hardship to the alien, the alien's child, or the alien's parent."],[0,"(B) Physical presence"],[2,"Notwithstanding subsection (d)(2), for purposes of subparagraph (A)(ii) or for purposes of section 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996), an alien shall not be considered to have failed to maintain continuous physical presence by reason of an absence if the alien demonstrates a connection between the absence and the battering or extreme cruelty perpetrated against the alien. No absence or portion of an absence connected to the battering or extreme cruelty shall count toward the 90-day or 180-day limits established in subsection (d)(2). If any absence or aggregate absences exceed 180 days, the absences or portions of the absences will not be considered to break the period of continuous presence. Any such period of time excluded from the 180-day limit shall be excluded in computing the time during which the alien has been physically present for purposes of the 3-year requirement set forth in this subparagraph, subparagraph (A)(ii), and section 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996)."],[0,"(C) Good moral character"],[2,"Notwithstanding section 1101(f) of this title, an act or conviction that does not bar the Attorney General from granting relief under this paragraph by reason of subparagraph (A)(iv) shall not bar the Attorney General from finding the alien to be of good moral character under subparagraph (A)(iii) or section 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996), if the Attorney General finds that the act or conviction was connected to the alien's having been battered or subjected to extreme cruelty and determines that a waiver is otherwise warranted."],[0,"(D) Credible evidence considered"],[2,"In acting on applications under this paragraph, the Attorney General shall consider any credible evidence relevant to the application. The determination of what evidence is credible and the weight to be given that evidence shall be within the sole discretion of the Attorney General."],[0,"(3) Recordation of date"],[1,"With respect to aliens who the Attorney General adjusts to the status of an alien lawfully admitted for permanent residence under paragraph (1) or (2), the Attorney General shall record the alien's lawful admission for permanent residence as of the date of the Attorney General's cancellation of removal under paragraph (1) or (2)."],[0,"(4) Children of battered aliens and parents of battered alien children"],[0,"(A) In general"],[2,"The Attorney General shall grant parole under section 1182(d)(5) of this title to any alien who is a—"],[3,"(i) child of an alien granted relief under section 1229b(b)(2) or 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996); or"],[3,"(ii) parent of a child alien granted relief under section 1229b(b)(2) or 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996)."],[0,"(B) Duration of parole"],[2,"The grant of parole shall extend from the time of the grant of relief under subsection (b)(2) or section 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996) to the time the application for adjustment of status filed by aliens covered under this paragraph has been finally adjudicated. Applications for adjustment of status filed by aliens covered under this paragraph shall be treated as if the applicants were VAWA self-petitioners. Failure by the alien granted relief under subsection (b)(2) or section 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996) to exercise due diligence in filing a visa petition on behalf of an alien described in clause (i) or (ii) may result in revocation of parole."],[0,"(5) Application of domestic violence waiver authority"],[1,"The authority provided under section 1227(a)(7) of this title may apply under paragraphs (1)(B), (1)(C), and (2)(A)(iv) in a cancellation of removal and adjustment of status proceeding."],[0,"(6) Relatives of trafficking victims"],[0,"(A) In general"],[2,"Upon written request by a law enforcement official, the Secretary of Homeland Security may parole under section 1182(d)(5) of this title any alien who is a relative of an alien granted continued presence under section 7105(c)(3)(A) of title 22, if the relative—"],[3,"(i) was, on the date on which law enforcement applied for such continued presence—"],[4,"(I) in the case of an alien granted continued presence who is under 21 years of age, the spouse, child, parent, or unmarried sibling under 18 years of age, of the alien; or"],[4,"(II) in the case of an alien granted continued presence who is 21 years of age or older, the spouse or child of the alien; or"],[3,"(ii) is a parent or sibling of the alien who the requesting law enforcement official, in consultation with the Secretary of Homeland Security, as appropriate, determines to be in present danger of retaliation as a result of the alien's escape from the severe form of trafficking or cooperation with law enforcement, irrespective of age."],[0,"(B) Duration of parole"],[0,"(i) In general"],[3,"The Secretary may extend the parole granted under subparagraph (A) until the final adjudication of the application filed by the principal alien under section 1101(a)(15)(T)(ii) of this title."]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/8/1229b?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1229b. Cancellation of removal; adjustment of status","tname":"Aliens and Nationality","by":{"0":"3, 24, 53, 24"}},{"t":"usc","label":"8 U.S.C. § 1229c","url":"https://www.law.cornell.edu/uscode/text/8/1229c","subs":["(b)(1)(C)"],"by":{"0":"24"}},{"t":"usc","label":"8 U.S.C. § 1251","url":"https://www.law.cornell.edu/uscode/text/8/1251","subs":["(a)(2)(A)(iii)(1994)","(a)(4)(1988)","(a)(4)(B)(1988)","(a)(5)(1982)"],"by":{"0":"44, 12, 31, 7, 7"}},{"t":"usc","label":"8 U.S.C. § 136","url":"https://www.law.cornell.edu/uscode/text/8/136","subs":["(p)(1925)"],"by":{"0":"4"}},{"t":"usc","label":"18 U.S.C. § 16","url":"https://www.law.cornell.edu/uscode/text/18/16","subs":["(a)"],"by":{"0":"8, 28"}},{"t":"reg","label":"56 Fed. Reg. 50,033","url":"https://www.govinfo.gov/link/fr/56/50033","by":{"0":"20"}}]};